def solve():
    memo = {}

    def get_k(board):
        s = sum(board)
        if s == 0:
            return len(board)
        for x in board:
            if x > s - x:
                return len(board)
        return None

    def minimax(board):
        board = tuple(sorted(board))
        if board in memo:
            return memo[board]

        res = get_k(board)
        if res is not None:
            return res

        best_k = -1
        possible_choices = []
        n = len(board)
        for i in range(n):
            for j in range(i + 1, n):
                x, y = board[i], board[j]

                # B's turn: choose x+y or |x-y|
                board1 = list(board)
                board1.pop(j)
                board1.pop(i)
                board1.append(x + y)
                k1 = minimax(tuple(sorted(board1)))

                board2 = list(board)
                board2.pop(j)
                board2.pop(i)
                board2.append(abs(x - y))
                k2 = minimax(tuple(sorted(board2)))

                possible_choices.append(min(k1, k2))

        res = max(possible_choices)
        memo[board] = res
        return res

    for n in range(1, 16):
        memo = {}
        initial_board = tuple([1] * n)
        print(f"N={n}, k={minimax(initial_board)}")

solve()

